import re

def parse_duration(s: str) -> int:
    if not s or not s.strip():
        raise ValueError("Empty or whitespace-only input")

    UNITS = {
        's': 1,
        'm': 60,
        'h': 3600,
        'd': 86400,
        'w': 604800,
        'f': 1209600,
    }

    total = 0
    pos = 0
    n = len(s)

    def skip_ws():
        nonlocal pos
        while pos < n and s[pos].isspace():
            pos += 1

    skip_ws()

    # Must have at least one token
    if pos == n:
        raise ValueError("Empty input after stripping whitespace")

    found_token = False

    while pos < n:
        skip_ws()
        if pos == n:
            break

        # Optional '+' separator
        if s[pos] == '+':
            if not found_token:
                raise ValueError(f"Unexpected '+' at position {pos} before any token")
            pos += 1
            skip_ws()
            if pos == n:
                raise ValueError("Trailing '+' with no following token")

        # Expect a digit
        if not s[pos].isdigit():
            raise ValueError(f"Expected digit at {pos}, got {s[pos]!r}")

        # Read integer
        num_start = pos
        while pos < n and s[pos].isdigit():
            pos += 1
        number = int(s[num_start:pos])

        # Expect a unit
        if pos == n or not s[pos].isalpha():
            raise ValueError(f"Expected unit after number at position {pos}")

        unit_char = s[pos].lower()
        if unit_char not in UNITS:
            raise ValueError(f"Unknown unit {s[pos]!r} at position {pos}")
        pos += 1

        total += number * UNITS[unit_char]
        found_token = True

    if not found_token:
        raise ValueError("No valid tokens found")

    return total

